package com.kaifan.monster;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;
public class TimerReceiver extends android.content.BroadcastReceiver {
 static PendingIntent pending(Context c,String id,String label){return PendingIntent.getBroadcast(c,id.hashCode(),new Intent(c,TimerReceiver.class).setAction("timer:"+id).putExtra("id",id).putExtra("label",label),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static boolean schedule(Context c,String id,String label,long when){AlarmManager a=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent p=pending(c,id,label);boolean exact=Build.VERSION.SDK_INT<31||a.canScheduleExactAlarms();if(exact)a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);return exact;}
 public void onReceive(Context c,Intent intent){if(Intent.ACTION_BOOT_COMPLETED.equals(intent.getAction())){for(java.util.Map.Entry<String,?>e:c.getSharedPreferences("alarms",0).getAll().entrySet())try{JSONObject o=new JSONObject(e.getValue().toString());if(o.getLong("when")>System.currentTimeMillis())schedule(c,e.getKey(),o.getString("label"),o.getLong("when"));}catch(Exception ignored){}return;}String id=intent.getStringExtra("id");c.getSharedPreferences("alarms",0).edit().remove(id).apply();NotificationManager n=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("cooking","做菜与食材提醒",NotificationManager.IMPORTANCE_HIGH));PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class).putExtra("route","timers"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);try{n.notify(id.hashCode(),new Notification.Builder(c,"cooking").setSmallIcon(R.drawable.ic_monster).setContentTitle("开饭小怪提醒你").setContentText(intent.getStringExtra("label")).setContentIntent(open).setAutoCancel(true).build());}catch(SecurityException ignored){}}
}
